import random

# This generator targets inputs consumed by FUZZ_PARAM_STR in the QuicheBuffer fuzzers.
# The data type is arbitrary binary data, so we focus on producing valid, interesting
# byte sequences that exercise various sizes and content patterns while remaining valid.

MAX_SIZE = 2048  # The fuzzer caps Copy() inputs to 2048 bytes in one path.
ABS_MAX = 4096   # Hard cap per instructions.

def _biased_sizes(rng):
    # Return a list of candidate sizes emphasizing corner cases.
    common = [0, 1, 2, 3, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 511, 512, 1023, 1024, 1500, 1536, 1792, 1900, 2000, 2047, 2048]
    # Add a few random sizes within bounds.
    common += [rng.randint(0, MAX_SIZE) for _ in range(10)]
    # Ensure uniqueness and in-range
    uniq = [s for s in dict.fromkeys(common) if 0 <= s <= MAX_SIZE]
    rng.shuffle(uniq)
    return uniq

def _pattern_bytes(pattern_name, n, rng):
    # Generate n bytes according to a named pattern.
    if n <= 0:
        return b""
    if pattern_name == "zeros":
        return b"\x00" * n
    if pattern_name == "ones":
        return b"\xff" * n
    if pattern_name == "ascii":
        # Mix printable ASCII characters
        chars = [ord(c) for c in ("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_./:\n\r\t ")]
        return bytes(rng.choice(chars) for _ in range(n))
    if pattern_name == "incremental":
        start = rng.randrange(256)
        return bytes((start + i) & 0xFF for i in range(n))
    if pattern_name == "decremental":
        start = rng.randrange(256)
        return bytes((start - i) & 0xFF for i in range(n))
    if pattern_name == "alternating01":
        return bytes((i & 1) * 0xFF for i in range(n))
    if pattern_name == "highbit":
        # High-bit set values to exercise signed/unsigned handling
        vals = [0x80, 0x81, 0xFE, 0xFF]
        return bytes(rng.choice(vals) for _ in range(n))
    if pattern_name == "utf8_like":
        # Not necessarily valid UTF-8, but cluster around multi-byte ranges
        def gen():
            t = rng.random()
            if t < 0.5:
                return rng.randint(0x20, 0x7E)
            elif t < 0.7:
                return rng.randint(0xC2, 0xDF)
            elif t < 0.9:
                return rng.randint(0xE0, 0xEF)
            else:
                return rng.randint(0xF0, 0xF4)
        return bytes(gen() for _ in range(n))
    if pattern_name == "random":
        return rng.randbytes(n) if hasattr(rng, 'randbytes') else bytes(rng.getrandbits(8) for _ in range(n))
    return _pattern_bytes("random", n, rng)

def _compose_segments(total_len, rng):
    # Compose the buffer from multiple segments of different patterns.
    if total_len == 0:
        return b""
    # Determine number of segments safely. Maximum segments limited by total_len.
    theoretical_max = 4 if total_len >= 4 else total_len  # can't have more segments than bytes
    theoretical_max = max(1, theoretical_max)
    segs = rng.randint(1, theoretical_max)
    if segs <= 1:
        parts = [total_len]
    else:
        # We need segs-1 cut points chosen from positions 1..total_len-1.
        population = total_len - 1
        k = min(segs - 1, population)
        # If population is 0, fallback to single segment.
        if k <= 0:
            parts = [total_len]
        else:
            cuts = sorted(rng.sample(range(1, total_len), k))
            # If k < segs-1 because total_len was small, we will have fewer parts.
            parts = []
            prev = 0
            for c in cuts + [total_len]:
                parts.append(c - prev)
                prev = c
    patterns = [
        "zeros", "ones", "ascii", "incremental", "decremental",
        "alternating01", "highbit", "utf8_like", "random"
    ]
    rng.shuffle(patterns)
    out = bytearray()
    for i, ln in enumerate(parts):
        pat = patterns[(i + rng.randint(0, len(patterns)-1)) % len(patterns)]
        out += _pattern_bytes(pat, ln, rng)
    return bytes(out)

def _inject_interesting_substrings(buf, rng):
    # Insert known substrings that might be interesting within arbitrary binary.
    inserts = [
        b"",  # sometimes no-op
        b"\x00", b"\x00\x00", b"\x00\x00\x00\x00",
        b"\n", b"\r\n", b"\t",
        b"HTTP/1.1 ", b"GET / ", b"POST / ", b"Host: example.com\r\n",
        b"quiche", b"QUIC", b"TLS", b"ALPN",
    ]
    if not buf:
        return buf
    out = bytearray(buf)
    tries = rng.randint(0, 4)
    for _ in range(tries):
        s = rng.choice(inserts)
        if not s:
            continue
        if len(s) >= len(out):
            # Replace a slice from the start, truncated if needed.
            out[:len(out)] = s[:len(out)]
        else:
            pos = rng.randint(0, len(out) - len(s))
            out[pos:pos+len(s)] = s
    return bytes(out)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a size with strong bias to boundaries the fuzzer uses (<= 2048)
    sizes = _biased_sizes(rng)
    size = sizes[0] if sizes else rng.randint(0, MAX_SIZE)

    # Compose content using multiple patterns
    buf = _compose_segments(size, rng)

    # Optionally inject interesting substrings without breaking validity
    buf = _inject_interesting_substrings(buf, rng)

    # Ensure final size constraints
    if len(buf) > ABS_MAX:
        buf = buf[:ABS_MAX]
    return buf
